   277	void moe_sum(torch::Tensor& input,   // [num_tokens, topk, hidden_size]
   278	             torch::Tensor& output)  // [num_tokens, hidden_size]
   279	{
   280	  const int hidden_size = input.size(-1);
   281	  const auto num_tokens = output.numel() / hidden_size;
   282	  const int topk = input.size(1);
   283	
   284	  dim3 grid(num_tokens);
   285	  dim3 block(std::min(hidden_size, 1024));
   286	  const at::cuda::OptionalCUDAGuard device_guard(device_of(output));
   287	  const cudaStream_t stream = at::cuda::getCurrentCUDAStream();
   288	
   289	  switch (topk) {
   290	    case 2:
   291	      VLLM_DISPATCH_FLOATING_TYPES(input.scalar_type(), "moe_sum_kernel", [&] {
   292	        vllm::moe::moe_sum_kernel<scalar_t, 2><<<grid, block, 0, stream>>>(
   293	            output.data_ptr<scalar_t>(), input.data_ptr<scalar_t>(),
   294	            hidden_size);
   295	      });
   296	      break;
   297	
   298	    case 3:
   299	      VLLM_DISPATCH_FLOATING_TYPES(input.scalar_type(), "moe_sum_kernel", [&] {
   300	        vllm::moe::moe_sum_kernel<scalar_t, 3><<<grid, block, 0, stream>>>(
   301	            output.data_ptr<scalar_t>(), input.data_ptr<scalar_t>(),
   302	            hidden_size);
   303	      });
   304	      break;
   305	
   306	    case 4:
   307	      VLLM_DISPATCH_FLOATING_TYPES(input.scalar_type(), "moe_sum_kernel", [&] {
   308	        vllm::moe::moe_sum_kernel<scalar_t, 4><<<grid, block, 0, stream>>>(
   309	            output.data_ptr<scalar_t>(), input.data_ptr<scalar_t>(),
   310	            hidden_size);
   311	      });
   312	      break;
   313	
   314	    default:
   315	      at::sum_out(output, input, 1);
   316	      break;
   317	  }
   318	}
