   218	    tokens_cnts[(threadIdx.x + 1) * num_experts + i] = 0;
   219	  }
   220	  
   221	  // Count tokens per expert (each thread counts a subset)
   222	  for (size_t i = tid; i < numel; i += stride) {
   223	    ++tokens_cnts[(threadIdx.x + 1) * num_experts + topk_ids[i]];
   224	  }
   225	  
   226	  __syncthreads();
   227	  
   228	  // Prefix sum across threads for each expert
   229	  if (threadIdx.x < num_experts) {
   230	    tokens_cnts[threadIdx.x] = 0;
   231	    for (int i = 1; i <= num_threads; ++i) {
   232	      tokens_cnts[i * num_experts + threadIdx.x] +=
   233	          tokens_cnts[(i - 1) * num_experts + threadIdx.x];
   234	    }
   235	  }
   236	  
   237	  __syncthreads();
