   270	    expert_ids[i] = 0;
   271	  }
   272	  
   273	  // Initialize sorted_token_ids with numel (only for regions we'll write to)
   274	  if (threadIdx.x < num_experts) {
   275	    for (int i = cumsum[threadIdx.x]; i < cumsum[threadIdx.x + 1]; ++i) {
   276	      sorted_token_ids[i] = numel;
   277	    }
   278	  }
   279	  
   280	  __syncthreads();
   281	  
   282	  // Sort tokens by expert
   283	  for (size_t i = tid; i < numel; i += stride) {
