   153	    int64_t const stride = blockDim.x;
   154	    int64_t const num_elems_in_col = num_cols / ELEM_PER_THREAD;
   155	
   156	    for (int elem_index = start_offset; elem_index < num_elems_in_col;
   157	         elem_index += stride) {
   158	      dest_row_ptr[elem_index] = source_row_ptr[elem_index];
   159	    }
